107	// Wrap a state change in a view transition when the platform offers one and
108	// the user has not asked for reduced motion; otherwise apply it directly.
109	function withScreenTransition(update: () => void, done?: () => void) {
110	  const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
111	  if (
112	    typeof document.startViewTransition !== "function" ||
113	    reduceMotion ||
114	    document.visibilityState === "hidden" // nothing to animate off-screen
115	  ) {
116	    update();
117	    done?.();
118	    return;
119	  }
120	  const transition = document.startViewTransition(() => {
121	    flushSync(update);
122	  });
123	  // A skipped or aborted transition (hidden tab, rapid re-entry) rejects
124	  // `finished`; that is normal, so swallow it and always run the cleanup.
125	  void transition.finished
126	    .catch(() => {})
127	    .then(() => done?.());
128	}
